import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"Web App Guide","description":"","frontmatter":{},"headers":[],"relativePath":"web-app.md","filePath":"web-app.md"}'),i={name:"web-app.md"};function n(s,e,d,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="web-app-guide" tabindex="-1">Web App Guide <a class="header-anchor" href="#web-app-guide" aria-label="Permalink to &quot;Web App Guide&quot;">​</a></h1><p>Sky Style combines live weather, your saved closet, and an AI recommendation in one dashboard. This guide is split into focused pages covering each area of the app.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ol><li>Create an account at <a href="https://skystyle.app" target="_blank" rel="noreferrer">skystyle.app</a> by signing in with GitHub or Google.</li><li>On the dashboard, choose a location manually or permit location access.</li><li>Add the clothes you actually own in <strong>Closet</strong>.</li><li>Generate a recommendation and use follow-up questions to refine it.</li></ol><p>New here? Try the <a href="https://skystyle.app/#demo" target="_blank" rel="noreferrer">no-login Live Demo</a> first to see real weather data.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><ul><li><strong><a href="./dashboard.html">Dashboard &amp; Closet</a></strong> — recommendation modes, follow-up questions, Bring Your Own Key, and your wardrobe.</li><li><strong><a href="./settings.html">Settings</a></strong> — profile, units, appearance, preferences, dashboard behaviour, layout &amp; spacing, and tutorials.</li><li><strong><a href="./security-and-privacy.html">Security &amp; Privacy</a></strong> — 2FA, passkeys, API keys, security log, data export, and account deletion.</li><li><strong><a href="./automatic-recommendations.html">Automatic Recommendations</a></strong> — schedule exact-time outfit recommendations with a manual location.</li><li><strong><a href="./api-dashboard.html">API Dashboard</a></strong> — manage API keys, allocate credits, and view per-key balances.</li><li><strong><a href="./account-and-support.html">Account &amp; Support</a></strong> — the account hub, plans, feedback, inbox, changelog, and service status.</li></ul><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Sky Style keeps three balances distinct:</p><table tabindex="0"><thead><tr><th>Balance</th><th>Use</th></tr></thead><tbody><tr><td>$ Credit (AUD)</td><td>Convert $1.00 into 50 API Credit for a key you choose. Pro receives $1.00 each calendar month.</td></tr><tr><td>API Credit</td><td>Per-key balance consumed by public API requests.</td></tr><tr><td>App Credit</td><td>In-app balance, including developer gifts and API fallback when a key&#39;s API Credit is empty. Pro receives 50 App Credits each day.</td></tr></tbody></table><p>API credit purchases are not live yet; the app&#39;s donation prompt is intentionally informational. See <a href="./api-dashboard.html#credits">API Dashboard → Credits</a> for details.</p>',11)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
